extractor:
function extract(raw, memory, info) {
  var TICK = 48;
  if (!memory) memory = {};
  if (!info) info = {};
  function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
  var screen = (raw && typeof raw.screen === 'string') ? raw.screen : 'unknown';
  var st = { screen: screen, over: !!(raw && raw.over), waiting: false, armed: false, ball: 'none', ballDx: null, ballUp: null, landMs: null, landDx: null, catchNow: null, canReach: null, spotDx: null, shotBricks: null, gapLeft: null, gapStay: null, gapRight: null };
  if (!raw || typeof raw !== 'object') { memory.sp = false; return st; }

  /* things the reader reports that are not known here: keep position and size */
  var known = { playing: 1, screen: 1, over: 1, score: 1, highscore: 1, lives: 1, level: 1, court: 1, paddle: 1, ball: 1, bricks: 1 };
  var unk = [], uk, uv;
  for (uk in raw) {
    if (known[uk] === 1) continue;
    uv = raw[uk];
    if (uv && typeof uv === 'object' && uv.length && typeof uv[0] === 'object') uv = uv[0];
    if (uv && typeof uv === 'object' && typeof uv.x === 'number' && typeof uv.y === 'number' && unk.length < 3) unk.push({ kind: String(uk), x: Math.round(uv.x), y: Math.round(uv.y), w: num(uv.w, null), h: num(uv.h, null) });
  }
  if (unk.length) st.unknown = unk;

  /* ms one decision lasts, measured from the game clock when it is given */
  var lag = num(info.lagMs, 0);
  if (lag < 0) lag = 0;
  if (lag > 500) lag = 500;
  var dtk = TICK, now = num(info.nowMs, null), dd;
  if (now !== null) {
    if (typeof memory.t === 'number') {
      dd = now - memory.t;
      if (dd >= 16 && dd <= 400) memory.dt = Math.max(16, Math.round(dd / 16) * 16);
    }
    memory.t = now;
  }
  if (typeof memory.dt === 'number') dtk = memory.dt;

  var pd = raw.paddle, bl = raw.ball, ct = raw.court, br = raw.bricks;
  var inGame = !!(pd && bl && ct) && screen !== 'menu' && screen !== 'gameover' && screen !== 'loading';
  var vx = inGame ? num(bl.vx, 0) : 0, vy = inGame ? num(bl.vy, 0) : 0;
  var moving = inGame && (typeof bl.moving === 'boolean' ? bl.moving : (vx !== 0 || vy !== 0));
  var resting = inGame && !moving;
  var waiting = screen === 'menu' || screen === 'gameover' || resting;
  /* Space only registers on a fresh press: armed on every other waiting decision */
  var armed = waiting && !memory.sp;
  memory.sp = armed;
  st.waiting = waiting;
  st.armed = armed;
  if (!inGame) { memory.pvy = 0; memory.pl = null; return st; }

  var r = num(bl.r, 5), pw = num(pd.w, 100), half = pw / 2;
  var px = num(pd.x, null), pcx = num(pd.cx, px === null ? null : px + half);
  var bx = num(bl.x, null), by = num(bl.y, null), pyTop = num(pd.y, null);
  var cLeft = num(ct.left, null), cRight = num(ct.right, null), cTop = num(ct.top, null);
  if (pcx === null || bx === null || by === null || pyTop === null || cLeft === null || cRight === null || cTop === null) { memory.pvy = 0; memory.pl = null; return st; }
  var cell = num(ct.cell, 17), pspeed = num(pd.speed, 340);
  var minC = num(pd.minX, cLeft) + half, maxC = num(pd.maxX, cRight - pw) + half;
  /* lines the ball centre bounces on: paddle top, side walls, top wall */
  var PY = pyTop - r, WL = cLeft + r, WR = cRight - r, WT = cTop + r;
  var step = pspeed * dtk / 1000;
  if (!(step > 1)) step = 1;
  var dir = pd.dir === 1 ? 1 : (pd.dir === -1 ? -1 : 0);
  /* paddle centre at the moment this decision takes effect */
  var cxE = pcx + dir * pspeed * lag / 1000;
  if (cxE < minC) cxE = minC;
  if (cxE > maxC) cxE = maxC;
  st.ballDx = Math.round(bx - cxE);
  st.ballUp = Math.round(PY - by);
  if (resting) { st.ball = 'rest'; memory.pvy = 0; memory.pl = null; return st; }
  var sp = Math.sqrt(vx * vx + vy * vy);
  if (!(sp > 1)) { memory.pvy = 0; return st; }
  if (memory.pvy > 0 && vy < 0) { memory.fl = (memory.fl || 0) + 1; memory.pl = null; }
  memory.pvy = vy;

  /* live bricks as rectangles, parsed again only when the grid changes */
  var rows = br && br.rows, key = '';
  if (rows && typeof rows.join === 'function') key = rows.join('/');
  var bricks = memory.bl;
  if (!bricks || key === '' || memory.bk !== key) {
    bricks = [];
    var j, i, s, n, ch, i0, o;
    if (key !== '') {
      for (j = 0; j < rows.length; j++) {
        s = rows[j];
        if (typeof s !== 'string') continue;
        n = s.length;
        i = 0;
        while (i < n) {
          ch = s.charAt(i);
          if (ch === '.' || ch === ' ') { i++; continue; }
          i0 = i;
          while (i < n && s.charAt(i) === ch) i++;
          bricks.push({ x0: cLeft + i0 * cell, y0: cTop + j * cell, x1: cLeft + i * cell, y1: cTop + (j + 1) * cell });
        }
      }
    } else if (br && br.lowest && br.lowest.length) {
      for (j = 0; j < br.lowest.length; j++) {
        o = br.lowest[j];
        if (o && typeof o.x === 'number' && typeof o.y === 'number') bricks.push({ x0: o.x, y0: o.y, x1: o.x + num(o.w, cell), y1: o.y + num(o.h, cell) });
      }
    }
    memory.bl = bricks;
    memory.bk = key;
  }
  var nb = bricks.length;

  /* follow the ball (velocity in px/s) through wall and brick bounces until it is back at paddle height */
  function fly(x, y, ax, ay, alive, left, maxT, maxN) {
    var t = 0, hits = 0, tFirst = -1, cnt = 0, bt, kind, bi, tt, k, b, q, c;
    if (ay > 0 && y > PY + 0.01) return { land: false, lost: true, cleared: false, x: x, t: 0, vy: ay, hits: 0, tFirst: -1 };
    while (cnt < maxN && t <= maxT) {
      cnt++;
      bt = 1e9; kind = 0; bi = -1;
      if (ay > 0) { tt = (PY - y) / ay; if (tt < 0) tt = 0; bt = tt; kind = 3; }
      else if (ay < 0) { tt = (WT - y) / ay; if (tt < 0) tt = 0; bt = tt; kind = 2; }
      if (ax < 0) { tt = (WL - x) / ax; if (tt < 0) tt = 0; if (tt < bt) { bt = tt; kind = 1; } }
      else if (ax > 0) { tt = (WR - x) / ax; if (tt < 0) tt = 0; if (tt < bt) { bt = tt; kind = 1; } }
      for (k = 0; k < nb; k++) {
        if (!alive[k]) continue;
        b = bricks[k];
        q = 0;
        if (ax > 0) {
          tt = (b.x0 - r - x) / ax;
          if (tt >= 0 && tt < bt) { c = y + ay * tt; if (c >= b.y0 - r && c <= b.y1 + r) q = 1; }
        } else if (ax < 0) {
          tt = (b.x1 + r - x) / ax;
          if (tt >= 0 && tt < bt) { c = y + ay * tt; if (c >= b.y0 - r && c <= b.y1 + r) q = 1; }
        }
        if (!q) {
          if (ay < 0) {
            tt = (b.y1 + r - y) / ay;
            if (tt >= 0 && tt < bt) { c = x + ax * tt; if (c >= b.x0 - r && c <= b.x1 + r) q = 2; }
          } else if (ay > 0) {
            tt = (b.y0 - r - y) / ay;
            if (tt >= 0 && tt < bt) { c = x + ax * tt; if (c >= b.x0 - r && c <= b.x1 + r) q = 2; }
          }
        }
        if (q) { bt = tt; kind = q; bi = k; }
      }
      if (kind === 0) break;
      x += ax * bt; y += ay * bt; t += bt;
      if (bi >= 0) {
        alive[bi] = 0;
        hits++;
        if (tFirst < 0) tFirst = t;
        if (kind === 1) ax = -ax; else ay = -ay;
        if (hits >= left) return { land: false, lost: false, cleared: true, x: x, t: t, vy: ay, hits: hits, tFirst: tFirst };
      } else if (kind === 3) {
        return { land: true, lost: false, cleared: false, x: x, t: t, vy: ay, hits: hits, tFirst: tFirst };
      } else if (kind === 1) {
        ax = -ax;
      } else {
        ay = -ay;
      }
    }
    return { land: false, lost: false, cleared: false, x: x, t: t, vy: ay, hits: hits, tFirst: tFirst };
  }

  var alive = [], a0;
  for (a0 = 0; a0 < nb; a0++) alive.push(1);
  var f = fly(bx, by, vx, vy, alive, nb, 14, 80);
  if (f.lost) { st.ball = 'lost'; memory.pl = null; return st; }
  st.ball = vy < 0 ? 'up' : 'down';
  var target = cxE, shot = 0;
  if (f.land) {
    var landX = f.x, vyIn = f.vy, tAvail = f.t * 1000 - lag, leftAfter = nb - f.hits;
    if (typeof bl.landX === 'number' && isFinite(bl.landX) && f.hits === 0 && vy > 0 && Math.abs(bl.landX - landX) > 12) landX = bl.landX;
    var zone = half * 0.9, grab = half + r - 3;
    /* keep the plan of this flight while its landing prediction holds */
    var pl = memory.pl, ok = false, need;
    if (pl && Math.abs(pl.x - landX) < 1.5 && Math.abs(pl.vy - vyIn) < 3 && pl.n === leftAfter && Math.abs(pl.c - landX) <= zone + 2) {
      need = Math.abs(pl.c - cxE);
      if (need < 0.5 || need <= pspeed * (tAvail - 8) / 1000 + 0.5) ok = true;
    }
    if (!ok) {
      /* paddle positions reachable in whole decisions that still catch the ball; where the ball meets the paddle sets its new direction */
      var cands = [], kLo = Math.ceil((landX - zone - cxE) / step), kHi = Math.floor((landX + zone - cxE) / step), stride = Math.max(1, Math.ceil((kHi - kLo + 1) / 12)), kk, c;
      for (kk = kLo; kk <= kHi; kk += stride) { c = cxE + kk * step; if (c >= minC && c <= maxC) cands.push(c); }
      if (Math.abs(landX - minC) <= zone) cands.push(minC);
      if (Math.abs(landX - maxC) <= zone) cands.push(maxC);
      var best = null, bestVal = -1e9, ci, off, ox, mag, g, val, ticks, cosO, seed, fl = memory.fl || 0;
      for (ci = 0; ci < cands.length; ci++) {
        c = cands[ci];
        ticks = Math.ceil(Math.abs(c - cxE) / step - 0.02);
        if (ticks < 0) ticks = 0;
        if (ticks > 0 && ticks * dtk > tAvail - 8) continue;
        off = (landX - c) / half;
        ox = sp * off;
        mag = Math.sqrt(ox * ox + vyIn * vyIn);
        if (!(mag > 0)) continue;
        g = fly(landX, PY, ox / mag * sp, -vyIn / mag * sp, alive.slice(), leftAfter, 10, 40);
        cosO = vyIn / mag;
        if (g.cleared) val = 500 - g.t;
        else if (g.hits > 0) val = 100 + 10 * g.hits - (g.land ? g.t : 12) - 0.5 * g.tFirst;
        else {
          /* no brick on this bounce: vary the pick from flight to flight so the ball cannot loop */
          seed = Math.sin((fl + 1) * 12.9898 + (ci + 1) * 78.233) * 43758.5453;
          val = 10 * (seed - Math.floor(seed));
          if (Math.abs(off) < 0.12) val -= 20;
        }
        if (cosO < 0.5) val -= 80 * (0.5 - cosO);
        val -= 0.002 * Math.abs(c - cxE);
        if (val > bestVal) { bestVal = val; best = { x: landX, vy: vyIn, n: leftAfter, c: c, h: g.hits }; }
      }
      if (best) { memory.pl = best; pl = best; ok = true; }
      else memory.pl = null;
    }
    if (ok) { target = pl.c; shot = pl.h; }
    else { target = landX < minC ? minC : (landX > maxC ? maxC : landX); }
    st.landMs = Math.max(0, Math.round(tAvail));
    st.landDx = Math.round(landX - cxE);
    st.catchNow = Math.abs(landX - cxE) <= grab;
    st.canReach = Math.abs(landX - cxE) - grab <= pspeed * Math.max(0, tAvail) / 1000;
  } else if (!f.cleared) {
    /* no landing predicted yet: keep under the ball */
    target = bx < minC ? minC : (bx > maxC ? maxC : bx);
    memory.pl = null;
  } else {
    memory.pl = null;
  }

  /* what each action leaves between the paddle and the planned position */
  var pL = cxE - step, pR = cxE + step;
  if (pL < minC) pL = minC;
  if (pR > maxC) pR = maxC;
  st.spotDx = Math.round(target - cxE);
  st.shotBricks = shot;
  st.gapLeft = Math.round(Math.abs(target - pL));
  st.gapStay = Math.round(Math.abs(target - cxE));
  st.gapRight = Math.round(Math.abs(target - pR));
  return st;
}

teacher:
function teach(state) {
  if (!state || typeof state !== 'object') return 'stay';
  /* menu, game over or ball resting on the paddle: pulse Space */
  if (state.waiting) return state.armed ? 'space' : 'stay';
  var l = state.gapLeft, s = state.gapStay, r = state.gapRight;
  if (typeof l !== 'number' || typeof s !== 'number' || typeof r !== 'number') return 'stay';
  /* smallest remaining distance to the planned contact position; equal ones share */
  var m = Math.min(l, s, r), ids = [];
  if (s === m) ids.push('stay');
  if (l === m) ids.push('left');
  if (r === m) ids.push('right');
  if (ids.length === 1) return ids[0];
  var p = {}, i;
  for (i = 0; i < ids.length; i++) p[ids[i]] = 1 / ids.length;
  return p;
}
